{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Pamiparib, the closest analogue (Morgan 0.2763), has high oral bioavailability with near-complete absorption in humans; its fused fluorinated lactam/heteroaromatic core and basic amine are shared with the query, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "CP-409,092, which shares the N-methylaminomethylphenyl substituent and a lactam-fused heteroaromatic, had 69% relative oral bioavailability in humans, supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Vonoprazan, containing the same N-methylaminomethylphenyl motif and a fluorophenyl group, was estimated at 36% oral bioavailability in humans, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Milrinone, a smaller heteroaromatic lactam, showed ~92% absolute oral bioavailability in healthy men, demonstrating that this class can be well absorbed despite polar/lactam features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Safinamide, a fluorinated benzyl ether amine, had 95% absolute oral bioavailability in humans, supporting high F for a moderately lipophilic basic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Mizolastine, a fluorophenyl benzimidazole-piperidine, had ~69% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Sunitinib, a fluorinated oxindole with a basic amine side chain, had ~50% absolute oral bioavailability in humans, supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Entrectinib, a larger heteroaromatic amine, has >50% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A water-soluble non-metabolized TC analogue with a fluorinated oxindole and basic amine showed ~10% oral bioavailability due to very slow absorption; this is the only affirmative low-F evidence, but its lower similarity and absorption-limited mechanism reduce transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable human evidence, including the closest pamiparib analogue (high/near-complete absorption) and multiple structurally related drugs with absolute F of 36-95%, supports high oral bioavailability (F≥20%). The single low-F analogue is less similar and mechanistically absorption-limited, so it does not outweigh the consistent high-F evidence.",
  "evidence_gaps": [
    "No direct human PK data for the query molecule",
    "Morgan similarities are modest (0.19-0.28), limiting exact transfer",
    "No direct data on intestinal permeability, efflux, or first-pass metabolism for the query",
    "The one low-F analogue has a different absorption mechanism and lower similarity"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

